import re
with open('pandas/_libs/tslibs/period.pyx', 'r') as f:
    content = f.read()

old = '''cdef str period_format(int64_t value, int freq, object fmt=None):
    cdef:
        int freq_group

    if value == NPY_NAT:
        return "NaT"

    if isinstance(fmt, str):
        # Encode using current locale, in case fmt contains non-utf8 chars
        fmt = <bytes>util.string_encode_locale(fmt)

    if fmt is None:
        freq_group = get_freq_group(freq)
        if freq_group == FR_ANN:
            fmt = b"%Y"
        elif freq_group == FR_QTR:
            fmt = b"%FQ%q"
        elif freq_group == FR_MTH:
            fmt = b"%Y-%m"
        elif freq_group == FR_WK:
            left = period_asfreq(value, freq, FR_DAY, 0)
            right = period_asfreq(value, freq, FR_DAY, 1)
            return f"{period_format(left, FR_DAY)}/{period_format(right, FR_DAY)}"
        elif freq_group == FR_BUS or freq_group == FR_DAY:
            fmt = b"%Y-%m-%d"
        elif freq_group == FR_HR:
            fmt = b"%Y-%m-%d %H:00"
        elif freq_group == FR_MIN:
            fmt = b"%Y-%m-%d %H:%M"
        elif freq_group == FR_SEC:
            fmt = b"%Y-%m-%d %H:%M:%S"
        elif freq_group == FR_MS:
            fmt = b"%Y-%m-%d %H:%M:%S.%l"
        elif freq_group == FR_US:
            fmt = b"%Y-%m-%d %H:%M:%S.%u"
        elif freq_group == FR_NS:
            fmt = b"%Y-%m-%d %H:%M:%S.%n"
        else:
            raise ValueError(f"Unknown freq: {freq}")

    return _period_strftime(value, freq, fmt)'''

new = '''cdef str period_format(int64_t value, int freq, object fmt=None):
    cdef:
        int freq_group
        npy_datetimestruct dts
        int quarter

    if value == NPY_NAT:
        return "NaT"

    if fmt is None:
        # Fast path: directly format default representations without going
        # through c_strftime and locale encoding/decoding.
        freq_group = get_freq_group(freq)
        if freq_group == FR_ANN:
            get_date_info(value, freq, &dts)
            return f"{dts.year:04d}"
        elif freq_group == FR_MTH:
            get_date_info(value, freq, &dts)
            return f"{dts.year:04d}-{dts.month:02d}"
        elif freq_group == FR_BUS or freq_group == FR_DAY:
            get_date_info(value, freq, &dts)
            return f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d}"
        elif freq_group == FR_HR:
            get_date_info(value, freq, &dts)
            return f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d} {dts.hour:02d}:00"
        elif freq_group == FR_MIN:
            get_date_info(value, freq, &dts)
            return (
                f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d} "
                f"{dts.hour:02d}:{dts.min:02d}"
            )
        elif freq_group == FR_SEC:
            get_date_info(value, freq, &dts)
            return (
                f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d} "
                f"{dts.hour:02d}:{dts.min:02d}:{dts.sec:02d}"
            )
        elif freq_group == FR_MS:
            get_date_info(value, freq, &dts)
            return (
                f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d} "
                f"{dts.hour:02d}:{dts.min:02d}:{dts.sec:02d}."
                f"{(dts.us // 1000):03d}"
            )
        elif freq_group == FR_US:
            get_date_info(value, freq, &dts)
            return (
                f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d} "
                f"{dts.hour:02d}:{dts.min:02d}:{dts.sec:02d}."
                f"{dts.us:06d}"
            )
        elif freq_group == FR_NS:
            get_date_info(value, freq, &dts)
            return (
                f"{dts.year:04d}-{dts.month:02d}-{dts.day:02d} "
                f"{dts.hour:02d}:{dts.min:02d}:{dts.sec:02d}."
                f"{(dts.us * 1000 + dts.ps // 1000):09d}"
            )
        elif freq_group == FR_QTR:
            quarter = get_yq(value, freq, &dts)
            return f"{dts.year}Q{quarter}"
        elif freq_group == FR_WK:
            left = period_asfreq(value, freq, FR_DAY, 0)
            right = period_asfreq(value, freq, FR_DAY, 1)
            return f"{period_format(left, FR_DAY)}/{period_format(right, FR_DAY)}"
        else:
            raise ValueError(f"Unknown freq: {freq}")

    if isinstance(fmt, str):
        # Encode using current locale, in case fmt contains non-utf8 chars
        fmt = <bytes>util.string_encode_locale(fmt)

    return _period_strftime(value, freq, fmt)'''

assert old in content, "Old block not found"
content = content.replace(old, new)
with open('pandas/_libs/tslibs/period.pyx', 'w') as f:
    f.write(content)
print("Patched")
